import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig, random } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadArchivoBlack = makeLoadFont('ArchivoBlack');

const { fontFamily: archivoFamily } = loadArchivoBlack();



export type LEDScoreboardProps = Record<string, any>;

// Statically generate the decorative border dots to avoid recreating the array every frame
// Arranged as a continuous path to allow seamless rotation
const generateBorderDots = () => {
  const cols = 91; // 1456px width / 16px grid
  const rows = 44; // 704px height / 16px grid
  const dots = [];
  let id = 0;

  // Top: left to right
  for (let c = 1; c <= cols - 2; c++) {
    dots.push({ c, r: 1, id: id++ });
  }
  // Right: top to bottom
  for (let r = 2; r <= rows - 2; r++) {
    dots.push({ c: cols - 2, r, id: id++ });
  }
  // Bottom: right to left
  for (let c = cols - 3; c >= 1; c--) {
    dots.push({ c, r: rows - 2, id: id++ });
  }
  // Left: bottom to top
  for (let r = rows - 3; r >= 2; r--) {
    dots.push({ c: 1, r, id: id++ });
  }
  
  return { dots, totalPerimeter: id };
};

const { dots: staticBorderDots, totalPerimeter } = generateBorderDots();

// Pre-generate grid cells for the random LED reveal mask
const generateCells = () => {
  const COLS = 92; // 1472px inner width / 16
  const ROWS = 45; // 720px inner height / 16
  const TOTAL_CELLS = COLS * ROWS;
  const cells = [];
  
  for (let i = 0; i < TOTAL_CELLS; i++) {
    const c = i % COLS;
    const r = Math.floor(i / COLS);
    // Random reveal frame between 0 and 45 for each 16x16 block
    const revealFrame = Math.floor(random(i) * 45);
    cells.push({ c, r, revealFrame });
  }
  return cells;
};

const randomCells = generateCells();

// Individual dot component with a rotating chasing effect
const BorderDot: React.FC<{ c: number; r: number; id: number; color?: string }> = ({ c, r, id, color = "#ffffff" }) => {
  const frame = useCurrentFrame();
  
  const speed = 1.5; // Dots per frame rotation speed
  const shiftedIndex = (id - frame * speed) % totalPerimeter;
  const wrappedIndex = shiftedIndex < 0 ? shiftedIndex + totalPerimeter : shiftedIndex;
  
  const numPatterns = 26; // Number of dashes to ensure a seamless loop around the 258 total dots
  const numDotsInPattern = 10;
  
  // Map the continuous perimeter onto the repeating dash pattern
  const patternIndex = (wrappedIndex / totalPerimeter) * numPatterns * numDotsInPattern;
  const positionInSegment = patternIndex % numDotsInPattern;
  
  // Creates groups of 8 lit dots with 2 dot gaps
  const isOn = positionInSegment < 8;
  const opacity = isOn ? 0.9 : 0.1;

  return (
    <div style={{
      position: "absolute",
      left: c * 16 + 3, // Center 10px dot inside 16px cell
      top: r * 16 + 3,
      width: 10,
      height: 10,
      borderRadius: "50%",
      backgroundColor: color,
      opacity: opacity,
      boxShadow: opacity > 0.5 ? `0 0 10px ${color}` : "none",
      transition: "none"
    }} />
  );
};

// Reusable static text component for the main 3 lines
const MainText = ({ isGlow = false, line1Text, line2Text, line3Text, line1Color, line23Color }: any) => {
  return (
    <div style={{
      position: "absolute",
      inset: 0,
      display: "flex",
      flexDirection: "column",
      alignItems: "center",
      justifyContent: "center",
      gap: 16,
      filter: isGlow ? "blur(16px)" : "none",
      opacity: isGlow ? 0.4 : 1,
      zIndex: isGlow ? 3 : 1,
      pointerEvents: "none",
      textTransform: "uppercase",
      fontFamily: archivoFamily,
      textAlign: "center",
      boxSizing: "border-box"
    }}>
      <div style={{ fontSize: 200, color: line1Color, lineHeight: 0.85, letterSpacing: "0.02em" }}>
        {line1Text}
      </div>
      <div style={{ fontSize: 200, color: line23Color, lineHeight: 0.85, letterSpacing: "0.02em" }}>
        {line2Text}
      </div>
      <div style={{ fontSize: 200, color: line23Color, lineHeight: 0.85, letterSpacing: "0.02em" }}>
        {line3Text}
      </div>
    </div>
  );
};

// Reusable text component for the header
const HeaderText = ({ isGlow = false, text }: { isGlow?: boolean, text: string }) => (
  <div style={{
    position: "absolute",
    inset: 0,
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    filter: isGlow ? "blur(8px)" : "none",
    opacity: isGlow ? 0.6 : 1,
    zIndex: isGlow ? 3 : 1,
    color: "#ffffff",
    fontFamily: archivoFamily,
    fontSize: 72,
    letterSpacing: "0.2em",
    textTransform: "uppercase",
    boxSizing: "border-box"
  }}>
    {text}
  </div>
);

const LEDScoreboard: React.FC<LEDScoreboardProps> = ({
  backgroundColor = "#000000",
  boardColor = "#050505",
  transparentBackground = false,
  durationInSeconds = 10,
  headerText = "MALLOY STUDIO",
  line1Text = "MOTION",
  line2Text = "OF THE",
  line3Text = "WEEK",
  line1Color = "#ffffff",
  line23Color = "#304ffe",
}) => {
  const { width, height } = useVideoConfig();
  const frame = useCurrentFrame();
  const scale = Math.min(width / 1920, height / 1080);
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, display: "flex", justifyContent: "center", alignItems: "center" }}>
      {/* Canvas Scaler - Keeps internal logic locked to exact pixels for perfect dot-matrix alignment */}
      <div style={{
        width: 1920,
        height: 1080,
        transform: `scale(${scale})`,
        transformOrigin: "center center",
        display: "flex",
        justifyContent: "center",
        alignItems: "center"
      }}>
        
        {/* Scoreboard Outer Frame */}
        <div style={{
          width: 1520,
          height: 912,
          boxSizing: "border-box",
          backgroundColor: boardColor,
          border: "4px solid #1a1a1a",
          borderRadius: 24,
          padding: 24,
          display: "flex",
          flexDirection: "column",
          boxShadow: "0 30px 60px rgba(0,0,0,0.8), inset 0 0 100px rgba(0,0,0,0.5)"
        }}>
          
          {/* Header Panel (8px dot matrix) */}
          <div style={{
            width: "100%",
            height: 120,
            boxSizing: "border-box",
            border: "4px solid #1a1a1a",
            borderRadius: 16,
            position: "relative",
            overflow: "hidden",
            backgroundColor: boardColor
          }}>
            <HeaderText text={headerText} />
            {/* The Dot Mask perfectly slices the thick solid text underneath into LED circles */}
            <div style={{
              position: "absolute", inset: 0, zIndex: 2, pointerEvents: "none",
              backgroundImage: `radial-gradient(circle at center, transparent 35%, ${boardColor} 45%, ${boardColor} 100%)`,
              backgroundSize: "8px 8px"
            }} />
            <HeaderText text={headerText} isGlow />
          </div>

          {/* Main Display Panel (16px dot matrix) */}
          <div style={{
            flex: 1,
            marginTop: 24,
            boxSizing: "border-box",
            border: "4px solid #1a1a1a",
            borderRadius: 16,
            position: "relative",
            overflow: "hidden",
            backgroundColor: boardColor,
            boxShadow: "inset 0 0 0 4px #111"
          }}>
            
            {/* SVG Defs for Random Reveal Mask */}
            <svg width={0} height={0} style={{ position: "absolute" }}>
              <defs>
                <clipPath id="led-clip-path">
                  {randomCells.map((cell, i) => {
                    // Only render the 16x16 visibility rect if current frame passes its random reveal frame
                    if (frame < cell.revealFrame) return null;
                    return <rect key={i} x={cell.c * 16} y={cell.r * 16} width={16} height={16} />;
                  })}
                </clipPath>
              </defs>
            </svg>

            {/* Clipped Container revealing the dots randomly */}
            <div style={{
              position: "absolute",
              inset: 0,
              clipPath: "url(#led-clip-path)"
            }}>
              <MainText 
                line1Text={line1Text} line2Text={line2Text} line3Text={line3Text} 
                line1Color={line1Color} line23Color={line23Color} 
              />
              {/* 16px Dot Mask */}
              <div style={{
                position: "absolute", inset: 0, zIndex: 2, pointerEvents: "none",
                backgroundImage: `radial-gradient(circle at center, transparent 35%, ${boardColor} 45%, ${boardColor} 100%)`,
                backgroundSize: "16px 16px"
              }} />
              <MainText isGlow 
                line1Text={line1Text} line2Text={line2Text} line3Text={line3Text} 
                line1Color={line1Color} line23Color={line23Color} 
              />
            </div>
            
            {/* Rotating Loop Border Dots (rendered above mask to retain glow) */}
            <div style={{ position: "absolute", inset: 0, zIndex: 4, pointerEvents: "none" }}>
              {staticBorderDots.map(dot => (
                <BorderDot key={dot.id} {...dot} />
              ))}
            </div>
          </div>

        </div>
      </div>
    </AbsoluteFill>
  );
};

export default LEDScoreboard;